// 2025-1-27 08:57:00
// Millars n-fold
// https://tilings.math.uni-bielefeld.de/substitution/millars-n-fold/

#define PI 3.1415926535
#define rot(a) mat2(cos(a), sin(a), -sin(a), cos(a))

void mainImage(out vec4 O, vec2 U)
{
        vec2 R = iResolution.xy,
             u = .3*(U+U - R) / R.y;

        float Q2 = sqrt(2.), Q2f = Q2/2., s = 1. , S8 = sin(PI/8.), C8 = cos(PI/8.), T8=S8/C8;

        int type;

        type=2;


        for(int i =0; i<6; i++)
        {
                if(type==0)
                {
                        u = abs(u);
                        if(u.x<u.y)u = u.yx;
                        if(u.y + T8*u.x - Q2f*T8<0.){//1023
                                type=2;
                        }else{
                                type = 1;
                                u = rot(PI/4.) * u;
                                u.y -= .5;
                        }
                        u *= C8*2.;
                        s *= C8*2.;
                }else if(type == 1){
                        u = abs(u);
                        if(u.x+u.y<Q2f*.5/C8){
                                type=0;
                                u *= Q2f / S8;
                                s *= Q2f / S8;
                        }else{
                                // type=1
                                u.x-=C8*.5;
                                u.y-=S8*.5;
                                u = rot(PI/8.) * u;
                                u *= C8*2.;
                                s *= C8*2.;
                        }
                }else{// type==2
                        u = abs(u);//
                        if(u.x<u.y)u=u.yx;
                        if(u.x+u.y<S8*2.){
                                type =0;
                                u.x-=S8;//
                                u *= Q2f / S8;
                                s *= Q2f / S8;
                        }else{
                                type = 1;
                                u.x -= S8+C8/2.;//
                                u.y -= S8*.5;
                                u = rot(PI/8.) * u;
                                u *= C8*2.;
                                s *= C8*2.;
                        }

                }
        }

        /////type=2;

        u = abs(u);
        O = vec4(1,0,1,1);
        if(type==0){
                u.x -= Q2f;
                u = rot(PI/4.)*u;
                //O = vec4(.9, .3, .3, 1);
                O =mix(O, vec4(1), .4);
        }else if(type==1){
                u.x -= C8;
                u = rot(PI/8.) * u;
                //O = vec4(.3, .9, .3, 1);
                O =mix(O, vec4(1), .7);
        }else{
                if(u.x<u.y)u=u.yx;//
                u.x -= (S8+C8)*1.05;///////
                u = rot(PI/8.) * u;
                //O *= .6;
                //O = vec4(.3, .3, .9, 1);
                O =mix(O*.5, vec4(1), .1);
        }

        O -= smoothstep( .002, 0., abs(u.y)/s );
}
